from pathlib import Path
import re, base64

INDEX = Path("public/index.html")
WORKER = Path("src/worker.js")
SW = Path("public/sw.js")

OLD = "3.9.6-automation-approval-fix-r2"
NEW = "3.9.6-native-pdf-r3"

def read(path):
    return path.read_text(encoding="utf-8")

def write(path, text):
    path.write_text(text, encoding="utf-8")

def require(text, needle, label):
    if needle not in text:
        raise SystemExit("Missing anchor: " + label)

index = read(INDEX)
require(index, OLD, "3.9.6 r2 release id")
require(index, "function printStatementPdf(key)", "old print function")
require(index, 'showToast("سيُفتح نموذج الطباعة؛ اختر حفظ كملف PDF")', "old print toast")
index = index.replace(OLD, NEW)

pattern = re.compile('      function printStatementPdf\\(key\\) \\{.*?\\n      \\}\\n\\n      window\\.addEventListener\\("afterprint", cleanupStatementPrint\\);', re.S)
replacement = base64.b64decode("").decode("utf-8") + '\n\n      window.addEventListener("afterprint", cleanupStatementPrint);'
index, count = pattern.subn(lambda m: replacement, index, count=1)
if count != 1:
    raise SystemExit("Could not replace printStatementPdf")

for needle in [
    NEW,
    "statementBuildNativePdf",
    "statementPdfBuildBinary",
    "navigator.share",
    "Statement PDF export failed"
]:
    require(index, needle, needle)

write(INDEX, index)

worker = read(WORKER)
require(worker, 'const VERSION = "3.9.6";', "worker version 3.9.6")
require(worker, 'const RELEASE_ID = "' + OLD + '";', "worker r2 release")
worker = worker.replace(
    'const RELEASE_ID = "' + OLD + '";',
    'const RELEASE_ID = "' + NEW + '";',
    1
)
worker, n = re.subn(
    r'const UPDATE_SIGNAL_VERSION = "3\.9\.6[^"]*";',
    lambda _: 'const UPDATE_SIGNAL_VERSION = "3.9.6' + chr(0x2069) + '";',
    worker,
    count=1
)
if n != 1:
    raise SystemExit("Could not bump update signal")
write(WORKER, worker)

sw = read(SW)
require(sw, "salary-manager-v3.9.6-automation-approval-fix-r2", "sw r2 cache")
sw = sw.replace(
    "salary-manager-v3.9.6-automation-approval-fix-r2",
    "salary-manager-v3.9.6-native-pdf-r3",
    1
)
write(SW, sw)

print("3.9.6 r3 native PDF export applied")
